const input = Array.isArray($json) ? $json : [$json];
return input.map((closedWon) => {
  const satisfaction = `${closedWon.customerSatisfaction ?? ''}`.toLowerCase();
  const optOut = closedWon.reviewOptOut === true;
  const eligible = !optOut && (satisfaction === 'high' || satisfaction === 'positive');
  const daysSinceClosed = Number(closedWon.daysSinceClosed ?? 0);
  let touch;
  if (!eligible) touch = 'manager-route';
  else if (daysSinceClosed === 7) touch = 'D7-email';
  else if (daysSinceClosed === 10) touch = 'D10-sms';
  else if (daysSinceClosed === 14) touch = 'D14-final-email';
  else touch = 'wait';
  return { json: { ...closedWon, touch, reviewLink: eligible ? closedWon.reviewLink ?? 'https://g.page/r/REVIEW-LINK-PLACEHOLDER' : null, nextAction: touch === 'manager-route' ? 'Escalate to office manager for follow-up first.' : touch === 'wait' ? 'No touch today.' : 'Send approved review request.' } };
});
